js=T_JS + r'''
var PIN={4:7,5:5,6:4,7:6,8:14,9:13,10:15,12:1,13:2,14:3};
function sup(n){return String(n).replace(/\d/g,function(d){return '⁰¹²³⁴⁵⁶⁷⁸⁹'.charAt(+d);});}
function bits(x){var b=1;while(Math.pow(2,b)<=x)b++;return b;}
// Форма слова «бит» по показанной строке числа; у дробного — «бита».
function bt(s){s=String(s);if(/,/.test(s))return s+' бита';var n=parseInt(s,10)%100,n1=n%10;return s+' '+(n>10&&n<20?'бит':(n1>=2&&n1<=4?'бита':'бит'));}
// Отношение частот: до 10⁷ — восемь значащих цифр, больше — целиком, без экспоненты.
function rv(x){return x<1e7?fmt(x,8):x.toFixed(3).replace(/\.?0+$/,'').replace('.',',');}
// Отклонение: меньше 100 ppm — в ppm, до 1 % — в ppm и %, больше — в %.
function pe(e){var a=Math.abs(e);if(a<1e-12)return '0 ppm';if(a<1e-4)return sg(e)+fmt(e*1e6)+' ppm';if(a<1e-2)return sg(e)+fmt(e*1e6)+' ppm ('+sg(e)+fmt(e*100)+' %)';return sg(e)+fmt(e*100)+' %';}
function pz(x){return x>=1e4?fmt(x/1e4)+' %':fmt(x)+' ppm';}
function pq(x,lim){return lim>=1e4?fx(x/1e4,lim/1e4)+' %':fx(x,lim)+' ppm';}
function sync(){var m=S('mode');hideF('chip',m!=='bin');hideF('bits',m!=='tim');}
function init(){$('mode').addEventListener('change',sync);sync();}
function calc(){
var m=S('mode'),fi=P('fin'),fo=P('fout');
if(isNaN(fi)||isNaN(fo))return err('Заполните числами входную и нужную выходную частоту.');
if(!(fi>0)||!(fo>0))return err('Частоты должны быть больше нуля.');
if(fi>1e10)return err('Входная частота — не больше 10 ГГц.');
var r=fi/fo;
if(lt(r,1))return err('Делитель не повышает частоту: нужная '+si(fo,'Гц')+' больше входной '+si(fi,'Гц')+'.');
if(r>1e15)return err('Коэффициент деления больше 10¹⁵ — вне диапазона расчёта.');
var pp=OPT('ppm'),tl=OPT('tolp');
if(pp!==null){if(isNaN(pp))return err('Точность источника тактирования — число в ppm. Если её нет, оставьте поле пустым.');if(pp<0||pp>=1e5)return err('Точность источника тактирования — от 0 до 100 000 ppm.');}
if(tl!==null){if(isNaN(tl))return err('Допустимое отклонение — число. Если его нет, оставьте поле пустым.');if(tl<=0||tl>=1e6)return err('Допустимое отклонение — больше 0 и меньше 100 %.');}
var e,fa,lab,h=row('Отношение fвх / fвых',rv(r));
// Выбор — по наименьшему модулю относительной ошибки частоты r/N − 1; при равной ошибке — больший делитель.
function better(ae,bae,v,bv){return ae<bae-1e-12||(Math.abs(ae-bae)<=1e-12&&v>bv);}
if(m==='bin'){
 var any=S('chip')==='any',kc=0;while(Math.pow(2,kc)<r*(1-1e-12))kc++;
 var kf=Math.pow(2,kc)>r*(1+1e-12)?kc-1:kc,K=any?(kf===kc?[kc]:[kf,kc]):[4,5,6,7,8,9,10,12,13,14],bk=-1,be=0,bae=Infinity;
 for(var i=0;i<K.length;i++){var ee=r/Math.pow(2,K[i])-1;if(better(Math.abs(ee),bae,K[i],bk)){bk=K[i];be=ee;bae=Math.abs(ee);}}
 // Наилучший разряд без ограничения выводами — чтобы сказать, что у 4060 его нет.
 var uk=kf,ue=r/Math.pow(2,kf)-1;if(kc!==kf){var e2=r/Math.pow(2,kc)-1;if(better(Math.abs(e2),Math.abs(ue),kc,kf)){uk=kc;ue=e2;}}
 e=Math.abs(be)<1e-12?0:be;fa=fi/Math.pow(2,bk);lab='деление на 2'+sup(bk);
 h+=row('log₂(fвх / fвых)',fmt(Math.log(r)/Math.LN2))+row('Разрядов, чтобы опуститься до fвых: ⌈log₂(fвх/fвых)⌉',String(kc));
 if(kf!==kc)h+=row('Ближайшие степени двойки','÷2'+sup(kf)+' → '+si(fi/Math.pow(2,kf),'Гц')+' ('+pe(r/Math.pow(2,kf)-1)+'); ÷2'+sup(kc)+' → '+si(fi/Math.pow(2,kc),'Гц')+' ('+pe(r/Math.pow(2,kc)-1)+')');
 h+=row('Выбран выход','÷2'+sup(bk)+' (на '+rv(Math.pow(2,bk))+') → '+si(fa,'Гц'));
 if(!any){h+=row('Выход 74HC4060 по паспорту Nexperia','Q'+(bk-1)+' (нумерация с Q0), вывод '+PIN[bk]);
  if(uk!==bk)h+=row('Нужного разряда нет',uk<4||uk>14?'деление на 2'+sup(uk)+' у 74HC4060 недоступно: выведены ÷2⁴…2¹⁰ и ÷2¹²…2¹⁴':'выход ÷2'+sup(uk)+' у 74HC4060 не выведен — выведены ÷2⁴…2¹⁰ и ÷2¹²…2¹⁴');}}
else if(m==='int'){
 var Ml=Math.max(1,Math.floor(r*(1+1e-12))),C=[Ml,Ml+1],bm=0,bme=0,bmae=Infinity;
 for(var j=0;j<2;j++){var em=r/C[j]-1;if(better(Math.abs(em),bmae,C[j],bm)){bm=C[j];bme=em;bmae=Math.abs(em);}}
 e=Math.abs(bme)<1e-12?0:bme;fa=fi/bm;lab='M = '+bm;
 h+=row('Соседние целые коэффициенты','M = '+Ml+' → '+si(fi/Ml,'Гц')+' ('+pe(r/Ml-1)+'); M = '+(Ml+1)+' → '+si(fi/(Ml+1),'Гц')+' ('+pe(r/(Ml+1)-1)+')')+
  row('Коэффициент деления M — ближайший по частоте',String(bm))+row('Фактическая частота fвх / M',si(fa,'Гц'))+
  row('Разрядность','M − 1 = '+(bm-1)+' — '+bt(bits(bm-1))+'; M = '+bm+' — '+bt(bits(bm)));}
else{
 var A=S('bits')==='32'?4294967296:65536;
 if(lt(r,2))return err('Таймер делит не меньше чем на 2: при ARR = 0 счётчик стоит, поэтому наибольшая частота обновления — fвх/2 = '+si(fi/2,'Гц')+'.');
 var Nm=65536*A;
 if(gt(r,Nm))return err('Такую низкую частоту таймер не даст: наименьшая — fвх/(65 536·'+(A===65536?'65 536':'2³²')+') = '+si(fi/Nm,'Гц')+'. Нужен более медленный тактовый сигнал таймера, таймер с 32-битным ARR или счёт переполнений программой.');
 // Перебор всех PSC: для каждого — два соседних целых ARR + 1 около r/(PSC + 1) в пределах разрядности.
 var bp=0,ba=0,bte=0,btae=Infinity,cnt=0;
 for(var p=1;p<=65536;p++){var a0=r/p,L=[Math.floor(a0),Math.ceil(a0)];
  for(var q=0;q<2;q++){var a=Math.min(A,Math.max(2,L[q])),et=r/(p*a)-1,at=Math.abs(et);if(better(at,btae,a,ba)){bp=p;ba=a;bte=et;btae=at;}}}
 for(var p2=1;p2<=65536;p2++){var a1=r/p2,L2=[Math.floor(a1),Math.ceil(a1)],seen=-1;
  for(var q2=0;q2<2;q2++){var a2=Math.min(A,Math.max(2,L2[q2]));if(a2===seen)continue;seen=a2;if(Math.abs(Math.abs(r/(p2*a2)-1)-btae)<=1e-12)cnt++;}}
 e=Math.abs(bte)<1e-12?0:bte;fa=fi/(bp*ba);lab='PSC = '+(bp-1)+', ARR = '+(ba-1);
 h+=row('Предделитель PSC',String(bp-1))+row('Перезагрузка ARR',String(ba-1))+row('Коэффициент (PSC + 1)·(ARR + 1)',String(bp*ba))+
  row('Частота обновления fвх / ((PSC + 1)·(ARR + 1))',si(fa,'Гц'))+row('Тик счётчика (PSC + 1) / fвх',si(bp/fi,'с'))+
  row('Разрешение ШИМ: ARR + 1 шагов скважности',String(ba)+' — около '+bt(fmt(Math.log(ba)/Math.LN2,3)));
 if(cnt>1)h+=row('Та же погрешность у других пар',(cnt-1)+' — все с меньшим ARR');}
var d=pp===null?0:pp*1e-6,lo=(1+e)*(1-d)-1,hi=(1+e)*(1+d)-1,ae=Math.abs(e)*1e6,wp=Math.max(Math.abs(lo),Math.abs(hi))*1e6;
h+=row('Погрешность частоты из-за деления',pe(e));
if(pp!==null)h+=row('С учётом точности тактирования ±'+fmt(pp)+' ppm',Math.max(Math.abs(lo),Math.abs(hi))>=1e-2?'от '+sg(lo)+fmt(lo*100)+' до '+sg(hi)+fmt(hi*100)+' %':'от '+sg(lo)+fmt(lo*1e6)+' до '+sg(hi)+fmt(hi*1e6)+' ppm');
if(tl!==null)h+=row('Допустимое отклонение','±'+fmt(tl)+' ppm'+(tl>=100?' (±'+fmt(tl/1e4)+' %)':''));
var st;
if(tl!==null&&gt(ae,tl))st='Отклонение частоты '+pq(ae,tl)+' больше допустимого '+pq(tl,ae)+' — уже из-за деления, без учёта точности тактирования';
else if(tl!==null&&pp!==null&&gt(wp,tl))st='Риск: с учётом точности тактирования ±'+fmt(pp)+' ppm отклонение может достигать '+pq(wp,tl)+' — больше допустимого '+pq(tl,wp);
else if(tl===null)st='Недостаточно данных: допустимое отклонение частоты не задано; '+lab+', погрешность деления '+(ae===0?'0 ppm':pz(ae))+(pp!==null?', с учётом тактирования до '+pz(wp):', точность тактирования не задана');
else if(pp===null)st='Недостаточно данных: точность источника тактирования не задана — погрешность деления '+pq(ae,tl)+' не больше допустимой '+pq(tl,ae)+', но вклад кварца не учтён';
else st='Оценка: '+lab+', отклонение частоты не больше '+pq(wp,tl)+' при допустимом '+pq(tl,wp);
var n=m==='tim'?'Частота обновления таймера в режиме счёта вверх: PSC делит тактовую частоту на PSC + 1, счётчик считает от 0 до ARR — это ARR + 1 тиков (reference manual STM32, AN4013). Перебраны все PSC от 0 до 65 535 и для каждого — два соседних целых ARR; из пар с наименьшей погрешностью выбрана пара с наибольшим ARR: шаг скважности ШИМ 1/(ARR + 1) самый мелкий. Повторитель RCR и счёт вверх-вниз (center-aligned) меняют период — для них смотрите reference manual. ':
 (m==='int'?'Делитель на M: fвых = fвх/M. Частота обратно пропорциональна M, поэтому ближайший по частоте коэффициент — не всегда округление fвх/fвых: сравниваются оба соседних целых. ':'Каждый разряд двоичного счётчика делит частоту пополам: выход n-го разряда — fвх/2ⁿ. Из соседних степеней двойки выбрана ближайшая по частоте'+(S('chip')==='4060'?' среди выведенных у 74HC4060':'')+'. ');
n+='Погрешность деления — систематическая и точная; точность кварца в ppm добавляется к ней и меняется с температурой и временем — границы показаны для наихудшего сочетания.';
out(h+row('Статус',st)+note(n));
}
''',
about="""<div class="formula">Двоичный счётчик: fвых = fвх / 2ⁿ,&nbsp;&nbsp;разрядов не меньше ⌈log₂(fвх/fвых)⌉<br>Целочисленный делитель: fвых = fвх / M, M — ближайший по частоте из ⌊fвх/fвых⌋ и ⌊fвх/fвых⌋ + 1<br>Таймер STM32: fвых = fтакт / ((PSC + 1)·(ARR + 1)),&nbsp;&nbsp;PSC ≤ 65 535,&nbsp;&nbsp;1 ≤ ARR ≤ 2¹⁶ − 1 или 2³² − 1<br>Погрешность: δ = (fвх/fвых)/N − 1;&nbsp;&nbsp;с кварцем ±δк: от (1 + δ)(1 − δк) − 1 до (1 + δ)(1 + δк) − 1</div>
<p><b>Двоичный счётчик.</b> Каждый триггер счётчика делит частоту пополам, поэтому выход n-го разряда даёт fвх/2ⁿ, и чтобы опуститься до нужной частоты, нужно не меньше ⌈log₂(fвх/fвых)⌉ разрядов. Обычно нужная частота лежит между двумя степенями двойки — калькулятор показывает обе и выбирает ближайшую. У популярной микросхемы 74HC4060 (Nexperia; у CD4060B — та же цоколёвка с нумерацией выходов с Q4) 14 разрядов, но выведены не все: в паспорте Nexperia выходы Q3–Q9 и Q11–Q13 при нумерации с Q0, то есть деление на 2⁴…2¹⁰ и 2¹²…2¹⁴; деления на 2¹…2³ и 2¹¹ нет. Классический пример — часовой кварц 32 768 Гц: 2¹⁴ даёт 2 Гц, а 1 Гц нужен ещё один разряд.</p>
<p><b>Целочисленный делитель.</b> Программируемый делитель на M даёт fвх/M. Ближайший по частоте коэффициент — не обязательно округление fвх/fвых: частота обратно пропорциональна M, и при малых M ошибки соседних коэффициентов несимметричны. Например, при fвх/fвых = 2,45 округление даёт M = 2 и ошибку +22,5 %, а M = 3 — только −18,3 %. Поэтому калькулятор сравнивает оба соседних целых. Если в регистр записывают M − 1, как у таймеров STM32, разрядность считается по нему.</p>
<p><b>Таймер микроконтроллера.</b> В reference manual STM32 предделитель описан так: частота счётчика CK_CNT = fCK_PSC/(PSC + 1), делитель от 1 до 65 536 (RM0008). В режиме счёта вверх счётчик идёт от 0 до ARR, затем снова с 0 и формирует событие переполнения — период составляет ARR + 1 тиков; при ARR = 0 счётчик стоит. Отсюда частота обновления fтакт/((PSC + 1)·(ARR + 1)) — та же формула, что в ST AN4013, где у таймеров с повторителем добавлен множитель (RCR + 1); пример AN4013: 72 МГц, PSC = 1, ARR = 65 535 → 549,3 Гц. Одна формула не даёт однозначного ответа: одну и ту же частоту дают много пар, а при нецелом fтакт/fвых наилучшая пара не обязательно получается округлением. Калькулятор перебирает все PSC и для каждого — два соседних ARR, оставляет пары с наименьшей погрешностью и из них выбирает пару с наибольшим ARR. Для ШИМ это важно: скважность задаётся регистром сравнения с шагом 1/(ARR + 1), и чем больше ARR, тем мельче шаг. Тактовую частоту таймера берите из дерева тактирования в reference manual своего МК.</p>
<p><b>Погрешность и кварц.</b> Погрешность деления систематическая: она известна точно и не меняется. Источник тактирования добавляет свою: выходная частота пропорциональна тактовой, поэтому её относительное отклонение — (1 + δ)(1 ± δк) − 1, где δк — суммарная точность кварца в ppm по паспорту (допуск при 25 °C, температурная стабильность, старение). Калькулятор показывает обе границы и сравнивает наихудшую с допустимым отклонением. Если допуск уже нарушен одной погрешностью деления — это однозначный вывод; если только вместе с кварцем — риск.</p>
<p><b>Чем отличается от соседних страниц.</b> <a href="ne555-astabilnyy.html">Таймер NE555</a> задаёт частоту RC-цепью — её точность определяется допусками резисторов и конденсатора, а не кварцем. <a href="shim-srednee-napryazhenie.html">Калькулятор ШИМ</a> считает среднее напряжение и мощность по скважности. Нагрузочные конденсаторы, от которых зависит точность самого кварца, подбирает <a href="kvarc-kondensatory.html">калькулятор конденсаторов кварца</a>.</p>""",
example="""<p>Таймер с тактовой частотой 72 МГц, нужна частота 1 кГц. Общий коэффициент 72 000 больше 65 536, поэтому без предделителя 16-битный таймер не обойдётся. Точных пар много — PSC = 1 и ARR = 35 999, PSC = 2 и ARR = 23 999 и так далее; калькулятор выбирает <b>PSC = 1, ARR = 35 999</b>: погрешность 0, а шаг скважности ШИМ 1/36 000 — самый мелкий. С 32-битным ARR получится PSC = 0 и ARR = 71 999. Если кварц имеет точность ±50 ppm, частота 1 кГц будет в пределах от −50 до +50 ppm.</p>
<p>Частота 38 кГц от того же таймера: 72 000 000/38 000 = 1 894,74 — нецелое число. Лучшее целое — 1 895: <b>PSC = 0, ARR = 1 894</b>, частота 37,99 кГц, погрешность −138,9 ppm (−0,01389 %). Часовой кварц 32 768 Гц на 74HC4060 даёт 2 Гц с выхода Q13 (вывод 3) — деление на 2¹⁴.</p>""",
