js=T_JS + r'''
function calc(){
var di=P('di'),tr=P('tr'),dt=P('dt'),dv=P('dv'),c=P('c'),n=P('n'),kb=P('kb'),tl=P('tol'),f1=P('f1');
if([di,tr,dt,dv,c,n,kb,tl,f1].some(isNaN))return err('Заполните числами бросок тока, время нарастания, время отклика, допустимый провал, ёмкость, число конденсаторов, долю ёмкости под напряжением, допуск и частоту.');
if(di<=0||di>1000)return err('Бросок тока — больше 0 и не больше 1000 А.');
if(tr<=0||dt<=0)return err('Время нарастания тока и время отклика должны быть больше нуля.');
if(lt(dt,tr))return err('Время отклика Δt меньше времени нарастания тока tфр: стабилизатор успевает раньше, чем закончится фронт, и модель «ток отдаёт один конденсатор» неприменима.');
if(dv<=0)return err('Допустимый провал должен быть больше нуля.');
if(c<=0)return err('Ёмкость должна быть больше нуля.');
if(n<1||n>1000||Math.floor(n)!==n)return err('Число конденсаторов — целое от 1 до 1000.');
if(kb<=0||kb>100)return err('Ёмкость при рабочем напряжении — больше 0 и не больше 100 % номинала.');
if(tl<0||tl>80)return err('Допуск ёмкости — от 0 до 80 %.');
if(f1<=0)return err('Частота проверки импеданса должна быть больше нуля.');
var esr=OPT('esr'),esl=OPT('esl'),f2=OPT('f2');
if(esr!==null){if(isNaN(esr))return err('ESR — число. Если его нет в паспорте, оставьте поле пустым.');if(esr<=0)return err('ESR должно быть больше нуля.');}
if(esl!==null){if(isNaN(esl))return err('ESL — число. Если её нет в паспорте, оставьте поле пустым.');if(esl<=0)return err('ESL должна быть больше нуля.');}
if(f2!==null){if(isNaN(f2))return err('Верхняя граница диапазона — число. Для проверки на одной частоте оставьте поле пустым.');if(!gt(f2,f1))return err('Верхняя граница диапазона должна быть больше нижней.');}
// n одинаковых конденсаторов параллельно: ёмкость n·C, ESR/n, ESL/n — без индуктивности монтажа и общего участка питания.
var t=tl/100,Cn=n*c*kb/100,Cw=Cn*(1-t),Cx=Cn*(1+t),R=esr===null?NaN:esr/n,L=esl===null?NaN:esl/n,hr=esr!==null,hl=esl!==null;
var cmin=di*dt/dv,zt=dv/di,vr=hr?R*di:0,vl=hl?L*di/tr:0;
// Наибольший провал в модели: на фронте — ESL·ΔI/tфр, ESR·ΔI и заряд ΔI·tфр/(2C); после фронта ESL не действует, а провал на ёмкости
// растёт до конца Δt и с запасом считается так, будто весь ток ΔI шёл с самого начала: ΔI·Δt/C. Незаданные ESR и ESL — нули.
function dip(C){return vr+Math.max(vl+di*tr/(2*C),di*dt/C);}
var dN=dip(Cn),dW=dip(Cw),sN=di*dt/Cn,sW=di*dt/Cw;
function Z(f,C){var w=2*Math.PI*f;return Math.sqrt(R*R+Math.pow(w*L-1/(w*C),2));}
var zok=hr&&hl,fr=hl?1/(2*Math.PI*Math.sqrt(L*Cn)):NaN,fh=f2===null?f1:f2,zmx=NaN,fz=NaN;
// Реактивное сопротивление ωL − 1/(ωC) растёт и с частотой, и с ёмкостью, поэтому наибольший |Z| в диапазоне частот и допуска — в углах.
if(zok){var F=[f1,fh],K=[Cw,Cx];for(var i=0;i<2;i++)for(var j=0;j<2;j++){var z=Z(F[i],K[j]);if(!(z<=zmx)){zmx=z;fz=F[i];}}}
if(![cmin,Cn,dN,dW].every(isFinite)||(zok&&!isFinite(zmx)))return err('Значения вне диапазона надёжного расчёта.');
var mt=(!hr||!hl)?' — без '+(!hr&&!hl?'ESR и ESL':(!hr?'ESR':'ESL')):'';
var h=row('Нужная ёмкость по балансу заряда Cmin = ΔI·Δt/ΔV',si(cmin,'Ф'))+
 row('Ёмкость n·C при рабочем напряжении',si(Cn,'Ф')+(kb<100?' ('+fmt(kb)+' % номинала '+si(n*c,'Ф')+')':'')+(t>0?'; с допуском ±'+fmt(tl)+' % — от '+si(Cw,'Ф')+' до '+si(Cx,'Ф'):''))+
 row('Целевой импеданс Zцел = ΔV/ΔI',si(zt,'Ом'))+
 row('Провал на ёмкости ΔI·Δt/C',sx(sN,dv,'В')+(t>0?'; при ёмкости на нижней границе допуска — '+sx(sW,dv,'В'):''))+
 row('Падение на ESR ΔI·ESR/n',hr?si(vr,'В'):'не оценено — ESR не задано')+
 row('Выброс на ESL (ESL/n)·ΔI/tфр',hl?si(vl,'В'):'не оценён — ESL не задана')+
 row('Наибольший провал: ESR·ΔI + большее из (ESL·ΔI/tфр + ΔI·tфр/(2C)) и ΔI·Δt/C'+mt,sx(dN,dv,'В')+(gt(dN,dv)?' > ':' ≤ ')+sx(dv,dN,'В')+(t>0?'; при ёмкости на нижней границе допуска — '+sx(dW,dv,'В'):''));
h+=row('Собственный резонанс fрез = 1/(2π√(ESL·C))',hl?si(fr,'Гц')+(n>1?' — у одного конденсатора тот же: ESL/n и n·C':''):'не оценён — ESL не задана');
h+=row('Частоты броска — примерно до 0,35/tфр',si(0.35/tr,'Гц'));
if(zok){var a=Z(f1,Cn);h+=row(f2===null?'|Z| = √(ESR² + (2πf·ESL − 1/(2πfC))²) на '+si(f1,'Гц'):'|Z| = √(ESR² + (2πf·ESL − 1/(2πfC))²) на границах '+si(f1,'Гц')+' и '+si(fh,'Гц'),si(a,'Ом')+(f2===null?'':' и '+si(Z(fh,Cn),'Ом')));
 h+=row('Наибольший |Z|'+(f2===null?'':' в диапазоне')+(t>0?' с учётом допуска ёмкости':''),sx(zmx,zt,'Ом')+' на '+si(fz,'Гц')+(gt(zmx,zt)?' > ':' ≤ ')+'Zцел '+sx(zt,zmx,'Ом'));
 if(f2!==null&&!lt(fr,f1)&&!gt(fr,fh))h+=row('Наименьший |Z| — на резонансе внутри диапазона','ESR/n = '+si(R,'Ом'));}
else h+=row('Импеданс в диапазоне частот','не оценён — нужны ESR и ESL');
var st;
if(gt(dN,dv))st='Провал напряжения '+sx(dN,dv,'В')+' больше допустимого '+sx(dv,dN,'В')+mt+((!hr||!hl)?': с ними провал только больше':'')+'. Нужно больше ёмкости, меньше ESR и ESL или стабилизатор быстрее';
else if(t>0&&gt(dW,dv))st='Риск: при ёмкости на нижней границе допуска провал '+sx(dW,dv,'В')+' больше допустимого '+sx(dv,dW,'В')+mt;
else if(zok&&gt(zmx,zt))st='Риск: импеданс '+sx(zmx,zt,'Ом')+' на '+si(fz,'Гц')+' больше целевого '+sx(zt,zmx,'Ом')+' — составляющая тока этой частоты может дать провал больше допустимого';
else if(!hr||!hl)st='Недостаточно данных: '+(!hr&&!hl?'не заданы ESR и ESL':(!hr?'не задано ESR':'не задана ESL'))+' — '+(!hr&&!hl?'падение на ESR, выброс на ESL':(!hr?'падение на ESR':'выброс на ESL'))+' и импеданс не проверены; провал на ёмкости '+sx(sW,dv,'В')+' не больше допустимого '+sx(dv,sW,'В');
else st='Оценка: наибольший провал '+sx(t>0?dW:dN,dv,'В')+' не больше допустимого '+sx(dv,t>0?dW:dN,'В')+', импеданс '+(f2===null?'на '+si(f1,'Гц'):'в диапазоне '+si(f1,'Гц')+'…'+si(fh,'Гц'))+' не выше целевого '+sx(zt,zmx,'Ом');
var nt='Модель: пока стабилизатор не отреагировал (время Δt), весь бросок тока отдают блокировочные конденсаторы, потом — стабилизатор целиком. Провал на ёмкости посчитан с запасом, как будто ток ΔI шёл с самого начала, а не нарастал за tфр. ';
nt+='Конденсаторы параллельно: ёмкость n·C, ESR/n и ESL/n — без индуктивности монтажа и общего участка питания, которые на высоких частотах часто больше собственной ESL конденсатора. ';
nt+=(kb<100?'':'Ёмкость под напряжением взята равной номиналу — у керамики X5R и X7R её нужно взять по кривой DC bias изготовителя. ')+'Сравнение с целевым импедансом — критерий для частотной составляющей тока, а не точный расчёт провала: точно провал даёт моделирование цепи питания вместе со стабилизатором.';
out(h+row('Статус',st)+note(nt));
}
''',
about="""<div class="formula">Баланс заряда: Q = ΔI·Δt = C·ΔV&nbsp;&nbsp;⇒&nbsp;&nbsp;C ≥ ΔI·Δt/ΔV<br>Падение на ESR: ΔI·ESR;&nbsp;&nbsp;выброс на ESL: ESL·ΔI/tфр;&nbsp;&nbsp;наибольший провал: ESR·ΔI + max(ESL·ΔI/tфр + ΔI·tфр/(2C);&nbsp;ΔI·Δt/C)<br>fрез = 1/(2π√(ESL·C));&nbsp;&nbsp;|Z| = √(ESR² + (2πf·ESL − 1/(2πf·C))²);&nbsp;&nbsp;Zцел = ΔV/ΔI<br>n одинаковых параллельно: n·C, ESR/n, ESL/n;&nbsp;&nbsp;C = Cном·(доля под напряжением)·(1 ± допуск)</div>
<p><b>Ёмкость по броску тока.</b> Когда микросхема резко увеличивает потребление на ΔI, стабилизатор отвечает не сразу — через время Δt, которое определяется его быстродействием или индуктивностью пути к конденсатору побольше. Всё это время ток отдаёт блокировочный конденсатор и теряет заряд Q = ΔI·Δt. Заряд конденсатора Q = C·U (OpenStax, 8.1), поэтому напряжение на нём падает на ΔV = ΔI·Δt/C, и чтобы провал не превысил допустимый, нужно C ≥ ΔI·Δt/ΔV. Это баланс заряда: формула не зависит от типа конденсатора, но ёмкость в неё подставляют фактическую — с допуском и снижением под напряжением.</p>
<p><b>ESR и ESL.</b> У реального конденсатора есть последовательное сопротивление ESR и индуктивность ESL выводов и обкладок (ADI MT-101). Ток ΔI создаёт на ESR падение ΔI·ESR сразу и надолго, а на ESL — выброс L·dI/dt (OpenStax, 14.2), то есть ESL·ΔI/tфр при линейном нарастании тока за время tфр, только пока ток растёт. Поэтому наибольший провал — либо в конце фронта: ESR·ΔI + ESL·ΔI/tфр плюс небольшой провал ΔI·tфр/(2C) от заряда, отданного за фронт, — либо в конце интервала Δt: ESR·ΔI + ΔI·Δt/C. Второе слагаемое посчитано с запасом, как будто весь ток шёл с самого начала: точно, с нарастанием, было бы ΔI·(Δt − tфр/2)/C. Если ESR или ESL не заданы, калькулятор не подставляет вместо них ноль молча: превышение без них остаётся превышением (с ними только хуже), а вывод «не больше допустимого» он не делает — статус «Недостаточно данных».</p>
<p><b>Резонанс и импеданс.</b> Конденсатор с ESL — последовательная RLC-цепь: её импеданс √(ESR² + (2πf·ESL − 1/(2πf·C))²) (OpenStax, 15.3) убывает с частотой, пока преобладает ёмкость, на собственном резонансе 1/(2π√(ESL·C)) падает до ESR и выше растёт за счёт ESL — так описывает график импеданса ADI MT-101 и советует выбирать конденсатор с резонансом выше наибольшей частоты, на которой он должен работать. Реактивная часть 2πf·ESL − 1/(2πf·C) монотонно растёт и с частотой, и с ёмкостью, поэтому наибольший импеданс в диапазоне частот и в пределах допуска ёмкости всегда на одной из границ — калькулятор проверяет все четыре сочетания. Целевой импеданс Zцел = ΔV/ΔI — закон Ома для частотной составляющей тока: пульсации равны импедансу цепи питания, умноженному на переходный ток (так задаёт требования TI SPRAC76). Если в диапазоне импеданс выше целевого, составляющая тока этой частоты может дать провал больше допустимого — это «Риск», а не точный расчёт.</p>
<p><b>Какой диапазон частот.</b> Ток, нарастающий за время tфр, несёт составляющие примерно до 0,35/tфр. Это следует из закона заряда RC-цепи (OpenStax, 10.5): от 10 до 90 % экспонента нарастает за τ·ln 9 ≈ 2,2τ, а полоса такой цепи по уровню −3 дБ — 1/(2πτ), отсюда 2,2/(2π·tфр) ≈ 0,35/tфр. Нижняя граница — частота, выше которой стабилизатор уже не успевает за нагрузкой: её берут по полосе регулирования из паспорта стабилизатора.</p>
<p><b>Несколько конденсаторов.</b> Одинаковые конденсаторы параллельно дают ёмкость n·C, ESR/n и ESL/n; собственный резонанс у них тот же, что у одного. Индуктивность монтажа — дорожек и переходных отверстий — в этот счёт не входит, а на высоких частотах она часто больше ESL самого конденсатора; общий участок питания и вовсе не делится на n. Поэтому конденсаторы ставят у самых выводов питания, как советует ADI MT-101: электролитические — для низких частот, керамические 0,01–0,1 мкФ — для высоких.</p>
<p><b>Ёмкость под напряжением.</b> У многослойной керамики класса 2 (X5R, X7R) ёмкость под постоянным напряжением заметно ниже номинальной — это эффект DC bias, который описывают Murata и KYOCERA AVX; фактическое значение для конкретного типоразмера и напряжения дают кривые и онлайн-инструменты изготовителя (у Murata — SimSurfing). У керамики C0G ёмкость от напряжения почти не зависит (TDK). Калькулятор кривых не хранит и ничего не подставляет: долю от номинала вводят по данным изготовителя.</p>
<p><b>Чем отличается от соседних страниц.</b> <a href="rc-filtr.html">RC-фильтр</a> считает частоту среза фильтра в тракте сигнала, а здесь конденсатор шунтирует цепь питания, и важны его ёмкость под нагрузкой током, ESR, ESL и импеданс в полосе частот. <a href="impedans-rlc.html">Калькулятор импеданса RLC</a> считает ту же последовательную цепь на одной частоте. Нагрев самого стабилизатора считает <a href="linear-regulator-loss.html">калькулятор линейного стабилизатора</a>.</p>""",
example="""<p>Бросок тока микроконтроллера 100 мА с фронтом 10 нс, стабилизатор отвечает через 2 мкс, допустимый провал 100 мВ. По балансу заряда нужно 0,1·2 мкс/0,1 В = <b>2 мкФ</b>. Четыре конденсатора по 1 мкФ с допуском ±10 % (условно) дают 4 мкФ, а на нижней границе допуска — 3,6 мкФ; провал на ёмкости 50 и 55,56 мВ. Целевой импеданс 0,1 В/0,1 А = 1 Ом. Без ESR и ESL калькулятор пишет «Недостаточно данных».</p>
<p>Если по паспорту ESR = 10 мОм и ESL = 1 нГн на конденсатор (значения условные), на четырёх параллельно падение на ESR 0,25 мВ, выброс на ESL 0,25 нГн·0,1 А/10 нс = 2,5 мВ, наибольший провал 55,81 мВ при ёмкости на нижней границе допуска — не больше 100 мВ. Собственный резонанс 5,033 МГц, а наибольший импеданс в диапазоне 100 кГц…35 МГц — 0,4419 Ом на 100 кГц при ёмкости на нижней границе допуска — ниже целевого. Если же поставить один конденсатор 100 нФ, провал на ёмкости составит 0,1·2 мкс/100 нФ = 2 В — в двадцать раз больше допустимого: такой бросок без конденсатора большей ёмкости не выдержать.</p>""",
