 dict(type="select", id="sig", label="Входной сигнал", opts=[
  ("imp","Одиночный прямоугольный импульс"),
  ("sq","Меандр: импульс и пауза поровну")], val="imp"),
 dict(id="u", label="Амплитуда импульса U — скачок от 0 до U", unit="В", val="5"),
