 dict(id="T", label="Период меандра T", units=[("мкс",1e-6),("нс",1e-9),("мс",0.001),("с",1)], ui=0, val="100"),
 dict(id="r", label="Сопротивление R", units=[("Ом",1),("кОм",1e3),("МОм",1e6)], ui=1, val="10"),
