 dict(id="up", label="Порог следующего каскада Uпор", unit="В", val="2,5", hint="Порог переключения входа следующего каскада — по его паспорту; значение по умолчанию условное. Пусто — время спада до 10 % и 1 %"),
 dict(id="rs", label="Сопротивление источника Rи", units=[("Ом",1),("кОм",1e3)], ui=0, val="", hint="Выходное сопротивление источника импульсов. Пусто — источник идеальный"),
