js=T_JS + r'''
// Доля меньше 10⁻⁶ показывается словами: иначе вышли бы числа вроде 9,64·10⁻¹⁰ пВ.
function pc(x){return x<1e-6?'меньше 0,0001 %':fmt(100*x)+' %';}
function sync(){var q=S('sig')==='sq';hideF('ti',q);hideF('T',!q);}
function init(){$('sig').addEventListener('change',sync);sync();}
function calc(){
var df=S('sch')==='diff',sq=S('sig')==='sq',u=P('u'),r=P('r'),c=P('c');
if([u,r,c].some(isNaN))return err('Заполните числами амплитуду импульса, сопротивление и ёмкость.');
if(u<=0||u>1000)return err('Амплитуда импульса — больше 0 и не больше 1000 В.');
if(r<=0||c<=0)return err('Сопротивление и ёмкость должны быть больше нуля.');
var ti=NaN,T=NaN;
if(sq){T=P('T');if(isNaN(T))return err('Введите период меандра числом.');if(T<=0)return err('Период меандра должен быть больше нуля.');}
else{ti=P('ti');if(isNaN(ti))return err('Введите длительность импульса числом.');if(ti<=0)return err('Длительность импульса должна быть больше нуля.');}
var up=OPT('up'),rs=OPT('rs'),rl=OPT('rl');
if(up!==null){if(isNaN(up))return err('Порог — число в вольтах. Если его нет, оставьте поле пустым.');if(up<=0)return err('Порог должен быть больше нуля.');}
if(rs!==null){if(isNaN(rs))return err('Сопротивление источника — число. Если его нет, оставьте поле пустым.');if(rs<0)return err('Сопротивление источника не может быть отрицательным.');}
if(rl!==null){if(isNaN(rl))return err('Сопротивление нагрузки — число. Если его нет, оставьте поле пустым.');if(rl<=0)return err('Сопротивление нагрузки должно быть больше нуля.');}
// Эквивалент по правилам Кирхгофа. Дифференцирующая: ток контура через Rи, C и R∥Rн — τ = (Rи + R∥Rн)·C, выход = (Uвх − Uc)·R∥Rн/(Rи + R∥Rн).
// Интегрирующая: со стороны C источник U·Rн/(Rи + R + Rн) через (Rи + R)∥Rн — τ = (Rи + R)∥Rн·C.
var Rs=rs===null?0:rs,k,tau,lab;
if(df){var Rp=rl===null?r:r*rl/(r+rl);k=Rp/(Rs+Rp);tau=(Rs+Rp)*c;lab=rs===null&&rl===null?'τ = R·C':'τ = (Rи + R∥Rн)·C';}
else{var Ra=Rs+r;k=rl===null?1:rl/(Ra+rl);tau=(rl===null?Ra:Ra*rl/(Ra+rl))*c;lab=rs===null&&rl===null?'τ = R·C':'τ = ((Rи + R)∥Rн)·C';}
var U=k*u,ku=k<1?'k·U':'U',h=row('Постоянная времени '+lab,si(tau,'с'));
if(k<1)h+=row(df?'Амплитуда на выходе: k = R∥Rн/(Rи + R∥Rн)':'Установившееся напряжение: k = Rн/(Rи + R + Rн)',si(U,'В')+' — k = '+fmt(k));
if(!isFinite(tau)||!(tau>0))return err('Значения вне диапазона надёжного расчёта.');
var st,nt='',L1=Math.LN10,thr=up!==null;
if(!sq){
 var x=ti/tau,e1=Math.exp(-x);h+=row('Отношение tи/τ',fmt(x));
 if(df){var rem=U*e1,neg=U*(1-e1);
  h+=row('Выброс на фронте',si(U,'В'))+row('К концу импульса U·e^(−tи/τ)',e1<1e-6?pc(e1)+' выброса':si(rem,'В')+' — '+pc(e1)+' выброса')+row('Выброс на спаде −U·(1 − e^(−tи/τ))','−'+si(neg,'В'));
  if(thr){if(!lt(up,U)){h+=row('Порог '+fmt(up)+' В','выход его не достигает: амплитуда '+si(U,'В'));st='Выход не достигает порога: амплитуда '+sx(U,up,'В')+' не выше порога '+sx(up,U,'В')+(k<1?' — делитель сопротивления источника и нагрузки ослабил импульс':'');}
   else{var td=tau*Math.log(U/up);h+=row('Время спада до порога t = τ·ln(U/Uпор)',sx(td,ti,'с'));
    if(lt(td,ti)){h+=row('Длительность выходного импульса выше порога',sx(td,ti,'с')+' вместо '+sx(ti,td,'с'));st='Оценка: импульс укорочен до '+sx(td,ti,'с')+' на уровне '+fmt(up)+' В (вход '+sx(ti,td,'с')+'); на спаде выброс −'+si(neg,'В');}
    else{h+=row('Длительность выходного импульса выше порога',si(ti,'с')+' — весь входной импульс');st='Выходной импульс не укорочен: к концу входного импульса выход '+sx(rem,up,'В')+' ещё не ниже порога '+sx(up,rem,'В')+' — нужно τ меньше tи/ln(U/Uпор) = '+si(ti/Math.log(U/up),'с');}}}
  else{h+=row('Спад до 10 % и 1 % выброса: τ·ln 10 и τ·ln 100',si(tau*L1,'с')+' и '+si(2*tau*L1,'с'));st='Оценка: к концу импульса выход спадает до '+pc(e1)+' выброса; на спаде выброс −'+si(neg,'В');}
  nt='На спаде входа напряжение на конденсаторе не успевает измениться, и выход уходит ниже нуля на U·(1 − e^(−tи/τ)) — сверьте это с допустимым напряжением входа следующего каскада по его паспорту. ';}
 else{var U1=U*(1-e1),dev=1-(1-e1)/x;
  h+=row('Напряжение к концу импульса U·(1 − e^(−tи/τ))',si(U1,'В')+' — '+fmt(100*(1-e1))+' % от '+ku)+row('Отклонение от линейного нарастания 1 − (1 − e^(−x))/x, x = tи/τ',fmt(100*dev)+' %')+
   row('После импульса спадает U1·e^(−t/τ): до 1 % — за τ·ln 100',si(2*tau*L1,'с'));
  if(thr){if(!lt(up,U)){h+=row('Порог '+fmt(up)+' В','не достигается: установившееся напряжение '+si(U,'В')+' не выше порога');st='Порог не достигается: установившееся напряжение '+sx(U,up,'В')+' не выше порога '+sx(up,U,'В');}
   else{var tq=tau*Math.log(U/(U-up));h+=row('Задержка до порога t = τ·ln(U/(U − Uпор))',sx(tq,ti,'с'));
    if(!gt(tq,ti)){var tq2=ti+tau*Math.log(U1/up);h+=row('Выход выше порога','с '+sx(tq,tq2,'с')+' до '+sx(tq2,tq,'с')+' после фронта — '+si(tq2-tq,'с'));st='Оценка: к концу импульса '+sx(U1,up,'В')+' ('+fmt(100*(1-e1))+' % от '+ku+'), порог '+sx(up,U1,'В')+' достигнут через '+sx(tq,ti,'с')+'; отклонение от линейного нарастания '+fmt(100*dev)+' %';}
    else{h+=row('Порог за время импульса','не достигается: нужно '+sx(tq,ti,'с')+', импульс '+sx(ti,tq,'с'));st='Оценка: за время импульса выход не достигнет порога '+sx(up,U1,'В')+' — к концу импульса только '+sx(U1,up,'В')+', а до порога нужно '+sx(tq,ti,'с')+' при импульсе '+sx(ti,tq,'с');}}}
  else st='Оценка: к концу импульса '+si(U1,'В')+' ('+fmt(100*(1-e1))+' % от '+ku+'); отклонение от линейного нарастания '+fmt(100*dev)+' %';}}
else{
 var a=Math.exp(-T/(2*tau)),y=T/(4*tau),th=(1-a)/(1+a),vp=U/(1+a),vm=U*a/(1+a);
 h+=row('Отношение T/τ',fmt(T/tau));
 if(df){h+=row('Выброс на фронте U/(1 + e^(−T/(2τ)))',si(vp,'В'))+row('К концу полупериода U·e^(−T/(2τ))/(1 + e^(−T/(2τ)))',a<1e-6?pc(a/(1+a))+' от '+ku:si(vm,'В'))+
   row('Спад вершины U·tanh(T/(4τ))',si(U*th,'В')+' — '+fmt(100*th)+' % от '+ku)+row('Выброс на спаде','−'+si(vp,'В'));
  if(thr){if(!lt(up,vp)){h+=row('Порог '+fmt(up)+' В','выход его не достигает: выброс '+si(vp,'В'));st='Выход не достигает порога: выброс '+sx(vp,up,'В')+' не выше порога '+sx(up,vp,'В');}
   else if(!gt(up,vm)){h+=row('Длительность выходного импульса выше порога',si(T/2,'с')+' — весь полупериод');st='Выходной импульс не укорочен: к концу полупериода выход '+sx(vm,up,'В')+' ещё не ниже порога '+sx(up,vm,'В')+' — цепь почти без искажений передаёт меандр, сдвинув его к нулю';}
   else{var tm=tau*Math.log(vp/up);h+=row('Длительность выходного импульса выше порога τ·ln(Uвыбр/Uпор)',sx(tm,T/2,'с'));st='Оценка: выбросы ±'+si(vp,'В')+', выход выше порога '+sx(tm,T/2,'с')+' из '+sx(T/2,tm,'с')+'; спад вершины '+fmt(100*th)+' %';}}
  else st='Оценка: выбросы ±'+si(vp,'В')+', к концу полупериода '+(a<1e-6?pc(a/(1+a))+' от '+ku:si(vm,'В'))+'; спад вершины '+fmt(100*th)+' % от '+ku;
  nt='Выход меандра симметричен относительно нуля: постоянную составляющую конденсатор не пропускает. ';}
 else{var dvt=1-th/y;
  h+=row('Установившийся размах ΔU = U·tanh(T/(4τ))',si(U*th,'В'))+row('Наибольшее и наименьшее напряжение',si(vp,'В')+' и '+si(vm,'В'))+row('Среднее — половина '+ku,si(U/2,'В'))+
   row('Отличие от треугольника 1 − tanh(y)/y, y = T/(4τ)',fmt(100*dvt)+' %')+row('Установление от включения — около 5τ',si(5*tau,'с'));
  if(thr){if(!gt(up,vm)){h+=row('Порог '+fmt(up)+' В','выход всё время не ниже порога');st='Оценка: размах '+si(U*th,'В')+' вокруг '+si(U/2,'В')+' — выход всё время не ниже порога '+fmt(up)+' В, переключений нет';}
   else if(!lt(up,vp)){h+=row('Порог '+fmt(up)+' В','выход всё время не выше порога');st='Оценка: размах '+si(U*th,'В')+' вокруг '+si(U/2,'В')+' — выход всё время не выше порога '+fmt(up)+' В, переключений нет';}
   else{var t1=tau*Math.log((U-vm)/(U-up)),t2=tau*Math.log(vp/up);h+=row('Пересечение порога','через '+si(t1,'с')+' после фронта и через '+si(t2,'с')+' после спада');st='Оценка: размах '+si(U*th,'В')+' вокруг '+si(U/2,'В')+', порог '+fmt(up)+' В пересекается через '+si(t1,'с')+' после фронта и '+si(t2,'с')+' после спада';}}
  else st='Оценка: размах '+si(U*th,'В')+' вокруг среднего '+si(U/2,'В')+'; отличие от треугольника '+fmt(100*dvt)+' %';
  nt='Размах и среднее — установившиеся, после нескольких τ от включения. ';}}
nt+=(rs===null&&rl===null?'Источник считается идеальным, нагрузка не учтена — их можно задать, и τ и амплитуда пересчитаются. ':'Сопротивление источника и нагрузка учтены через эквивалентную схему: они меняют и τ, и амплитуду. ')+'Импульс идеально прямоугольный: фронт входа короче τ; R и C линейные, утечка и ёмкость монтажа не учитываются.';
out(h+row('Статус',st)+note(nt));
}
''',
about="""<div class="formula">Заряд через R: Uc(t) = U·(1 − e<sup>−t/τ</sup>),&nbsp;&nbsp;Ur(t) = U·e<sup>−t/τ</sup>,&nbsp;&nbsp;τ = R·C<br>Дифференцирующая, импульс: выброс U, к концу U·e<sup>−tи/τ</sup>, на спаде −U·(1 − e<sup>−tи/τ</sup>);&nbsp;&nbsp;до порога t = τ·ln(U/Uпор)<br>Интегрирующая, импульс: U·(1 − e<sup>−tи/τ</sup>);&nbsp;&nbsp;отклонение от линейного 1 − (1 − e<sup>−x</sup>)/x, x = tи/τ;&nbsp;&nbsp;до порога τ·ln(U/(U − Uпор))<br>Меандр, a = e<sup>−T/(2τ)</sup>: Umax = U/(1 + a),&nbsp;&nbsp;Umin = U·a/(1 + a),&nbsp;&nbsp;ΔU = U·tanh(T/(4τ)),&nbsp;&nbsp;среднее U/2<br>С источником и нагрузкой: дифференцирующая τ = (Rи + R∥Rн)·C, k = R∥Rн/(Rи + R∥Rн); интегрирующая τ = ((Rи + R)∥Rн)·C, k = Rн/(Rи + R + Rн)</div>
<p><b>Закон заряда.</b> Если на последовательную RC-цепь подать скачок напряжения U, конденсатор заряжается по экспоненте: Uc = U·(1 − e<sup>−t/τ</sup>) с постоянной времени τ = R·C, а ток и напряжение на резисторе спадают как U·e<sup>−t/τ</sup> (OpenStax, 10.5). Из этих двух выражений получается всё остальное: в интегрирующей цепи выход снимают с конденсатора, в дифференцирующей — с резистора. Так их называют и в учебниках импульсной техники — RC-цепь верхних частот работает как дифференцирующая, нижних — как интегрирующая (Millman и Taub, глава «Linear wave shaping»).</p>
<p><b>Дифференцирующая цепь.</b> На фронте импульса конденсатор не успевает зарядиться, и на резисторе — весь скачок U. Дальше выход спадает как U·e<sup>−t/τ</sup> и до порога Uпор опускается за t = τ·ln(U/Uпор). Если это меньше длительности импульса, импульс укорочен: на выходе остаётся короткий импульс длительностью τ·ln(U/Uпор). Если нет — к концу импульса выход ещё выше порога, и укорочения нет; для него нужно τ меньше tи/ln(U/Uпор). На спаде входа напряжение на конденсаторе снова не успевает измениться, и выход скачком уходит вниз на U, то есть до −U·(1 − e<sup>−tи/τ</sup>): отрицательный выброс тем ближе к −U, чем сильнее укорочен импульс. Его сравнивают с допустимым напряжением входа следующего каскада. Вместо условного «τ ≪ tи» калькулятор показывает остаток к концу импульса — e<sup>−tи/τ</sup>: при tи = 5τ это 0,67 % выброса.</p>
<p><b>Интегрирующая цепь.</b> Выход нарастает как U·(1 − e<sup>−t/τ</sup>) и к концу импульса достигает U·(1 − e<sup>−tи/τ</sup>). Идеальный интегратор дал бы линейное нарастание U·t/τ; отклонение от него к концу импульса 1 − (1 − e<sup>−x</sup>)/x при x = tи/τ, при малом x это около x/2. Значит, отклонение 1 % требует τ около 50·tи — и вместо условного «τ ≫ tи» калькулятор показывает само отклонение. Порога выход такой цепи достигает с задержкой τ·ln(U/(U − Uпор)), а если импульс короче — не достигает вовсе: так RC-цепь отсекает короткие помехи. После импульса конденсатор разряжается по той же экспоненте, и выход над порогом держится ещё τ·ln(U1/Uпор).</p>
<p><b>Меандр.</b> На периодическом сигнале с импульсом и паузой по T/2 напряжение на конденсаторе за импульс растёт от Umin к U, за паузу спадает от Umax к нулю. В установившемся режиме конец паузы совпадает с началом следующего импульса: Umax = U − (U − Umin)·a и Umin = Umax·a, где a = e<sup>−T/(2τ)</sup>. Отсюда Umax = U/(1 + a), Umin = U·a/(1 + a), а размах ΔU = U·(1 − a)/(1 + a) = U·tanh(T/(4τ)). Среднее — U/2, как у входа: средний ток конденсатора за период равен нулю. Для сравнения с треугольником идеального интегратора с размахом U·T/(4τ) калькулятор показывает отношение 1 − tanh(y)/y, y = T/(4τ). Выход дифференцирующей цепи — вход минус напряжение конденсатора: выбросы ±U/(1 + a) на фронтах, к концу полупериода U·a/(1 + a), спад вершины U·tanh(T/(4τ)). При τ ≪ T это короткие выбросы почти до ±U, при τ ≫ T — меандр с размахом U, сдвинутый к нулю, со спадом вершины около U·T/(4τ).</p>
<p><b>Источник и нагрузка.</b> Сопротивление источника и вход следующего каскада меняют и постоянную времени, и амплитуду. По правилам Кирхгофа (OpenStax, 10.3) в дифференцирующей цепи ток контура идёт через Rи, C и R∥Rн, поэтому τ = (Rи + R∥Rн)·C, а выход — доля R∥Rн/(Rи + R∥Rн) от напряжения Uвх − Uc. В интегрирующей цепи со стороны конденсатора источник — U·Rн/(Rи + R + Rн) через сопротивление (Rи + R)∥Rн. Если поля пустые, источник идеальный, а нагрузки нет — калькулятор так и пишет.</p>
<p><b>Чем отличается от соседних страниц.</b> <a href="rc-filtr.html">RC-фильтр</a> описывает ту же цепь в частотной области — частоту среза 1/(2πRC) для синусоиды, а здесь — форму сигнала во времени для импульсов. Время заряда до заданного процента считает <a href="zaryad-kondensatora.html">калькулятор заряда конденсатора</a>, длительность импульса одновибратора на RC-цепи — <a href="ne555-monostabilnyy.html">калькулятор NE555 в моностабильном режиме</a>.</p>""",
